<?php
function os_steps($step){echo '<ol class="os-steps" aria-label="Upload progress">';foreach(['Upload','Review','Confirm'] as $i=>$label)echo '<li'.($step===$i?' aria-current="step"':'').'><span>'.($i+1).'</span>'.e($label).'</li>';echo '</ol>';}
function os_tabs($kind,$pl){echo '<div class="tabs os-tabs"><a class="tab '.($kind==='Register'?'active':'').'" href="?page=outflow&platform='.e($pl).'&entry=register">Register Orders</a><a class="tab '.($kind==='Status'?'active':'').'" href="?page=outflow&platform='.e($pl).'&entry=status">Update Status</a></div>';}
function os_entry_page($kind){$pl=gm_platform($_GET);stock_platform($pl);$date=process_date($_GET['fulfillment_date']??date('Y-m-d'));os_tabs($kind,$pl);echo '<div class="card os-panel"><div class="om-hero"><div><h3>'.($kind==='Register'?'Register Orders':'Update Status').'</h3><p>'.e(om_shops()[$pl]).'</p></div><span class="badge '.($kind==='Register'?'ok':'info').'">'.($kind==='Register'?'Uploading open':'Existing orders only').'</span></div>';os_steps(0);if(!om_allowed()){echo '<p>Uploads are available to Admin and Operations Lead. Monitoring and downloads remain available.</p></div>';return;}
 om_form('om_stage',['kind'=>$kind,'platform'=>$pl,'shop'=>om_shops()[$pl]],true);echo '<div class="os-fields">';if($kind==='Register')echo '<label>Fulfillment Date<input type="date" name="fulfillment_date" max="'.date('Y-m-d').'" value="'.e($date).'" required></label><p class="os-help">Morning or afternoon upload. Normal fulfillment cutoff: 3 PM. Uploading stays open.</p>';else{echo '<label>Orders Created From<input type="date" name="coverage_from" max="'.date('Y-m-d').'" value="'.date('Y-m-d',strtotime('-30 days')).'" required></label><label>Through<input type="date" name="coverage_to" max="'.date('Y-m-d').'" value="'.date('Y-m-d').'" required></label><label>Export Time<input type="datetime-local" step="1" name="snapshot" value="'.date('Y-m-d\TH:i:s').'" required></label><p class="os-help wide">Use the creation-date coverage from your export: daily, weekly or monthly. Previous registered orders are matched too.</p>';}
 echo '<label class="wide">Original Platform Export<input type="file" name="file" accept=".xlsx" required></label></div>';if($kind==='Status'){echo '<label class="om-inline"><input type="checkbox" name="all_statuses" value="1" checked> Export includes All statuses within this range.</label><label class="om-inline"><input type="checkbox" name="coverage_ack" value="1" required> I confirm the shop, export time, date range and status coverage.</label><p class="os-help">Uncheck All statuses if the export was filtered. Unregistered orders will not be added.</p>';}else echo '<label class="om-inline"><input type="checkbox" name="fulfillment_ack" value="1" required> These orders are included in actual fulfillment.</label>';echo '<div class="om-actions"><button class="btn primary">Review File</button></div></form></div><div class="om-actions"><a class="btn ghost" href="?page=outflow&entry=history&platform='.e($pl).'">Upload History</a><a class="btn secondary" href="?page=order_monitor&platform='.e($pl).'">View Monitoring</a></div>';}
function os_upload_page($id){$b=om_upload($id);$reg=$b['kind']==='Register';$pl=$b['platform'];$review=$b['status']==='Review';$done=$b['status']==='Confirmed';$plan=$review?om_plan($b):null;$rows=$review?$plan['orders']:(json_decode($b['result_json']??'{}',true)['validation']??[]);$n=os_counts($rows);$filter=$_GET['review_filter']??'';if(!in_array($filter,['all','update','unchanged','unregistered','checking'],true)){$filter='unchanged';foreach(['update','checking','unregistered','unchanged'] as $c)if($n[$c]){$filter=$c;break;}}
 os_tabs($b['kind'],$pl);echo '<div class="card os-panel"><div class="om-hero"><div><h3>'.($reg?'Register Orders':'Update Status').'</h3><p>'.e(om_shops()[$pl]).'</p></div><span class="badge '.($done?'ok':'info').'">'.e($done?'Confirmed':($review?'No changes posted yet':$b['status'])).'</span></div>';os_steps($review?1:2);if($done)echo '<div class="alert success"><b>'.($reg?'Registration confirmed.':'Status updates confirmed.').'</b> '.e($reg?'New valid orders were reserved; physical stock was unchanged.':'Valid updates were recorded. First dispatches posted once; exclusions and conflicts remain in history.').'</div>';elseif(!$review)echo '<div class="alert info">This upload is '.e(strtolower($b['status'])).'. It cannot be confirmed again.</div>';
 $sourceCount=count(array_unique(array_column($b['rows'],'order')));$missingCount=count(array_filter($rows,fn($r)=>$r['action']==='Missing from covering export'));echo '<p class="os-source">'.e($b['filename']).' · Upload #'.$id.' · '.$sourceCount.' orders in file'.($missingCount?' · '.$missingCount.' registered orders missing from covering export':'').'</p>';foreach($b['meta']['warnings']??[] as $w)echo '<div class="alert warn">'.e($w).'</div>';
 $cats=['update'=>$reg?($done?'Registered':'New Orders'):($done?'Updated':'Will Update'),'unchanged'=>$reg?'Duplicates / Skipped':'Unchanged','unregistered'=>'Not Registered','checking'=>'Needs Checking'];if($reg)unset($cats['unregistered']);echo '<div class="os-results">';foreach($cats as $c=>$label){$url=['page'=>'outflow','platform'=>$pl,'upload_id'=>$id,'review_filter'=>$c];echo '<a class="os-result '.($filter===$c?'active':'').'" href="?'.e(http_build_query($url)).'"'.($filter===$c?' aria-current="true"':'').'><strong>'.$n[$c].'</strong><span>'.e($label).'</span></a>';}echo '</div><div class="os-row-heading"><span>'.e($filter==='all'?'All Rows':($cats[$filter]??'Rows')).'</span><a href="?page=outflow&platform='.e($pl).'&upload_id='.$id.'&review_filter=all">Show All Rows</a></div>';
 $visible=array_values(array_filter($rows,fn($r)=>$filter==='all'||os_category($r)===$filter));$size=10;$offset=min(max(0,(int)($_GET['review_offset']??0)),max(0,(int)floor(max(0,count($visible)-1)/$size)*$size));echo '<div class="om-table os-table"><table class="table" data-server-paginated="1"><thead><tr><th>Order ID</th><th>Current → Uploaded</th><th>'.($review?'On Confirmation':'Recorded Decision').'</th><th>Details / Correction</th></tr></thead><tbody>';
 foreach(array_slice($visible,$offset,$size) as $r){echo '<tr><td><b>'.e($r['order']).'</b>';if($r['order_record'])echo '<br><a href="?page=order_monitor&platform='.e($pl).'&order_id='.(int)$r['order_record']['id'].'">Order History</a>';echo '</td><td>'.e(($r['order_record']['platform_status']??'Not registered').' → '.$r['status']).'</td><td><b>'.e($r['action']).'</b><br>'.e(os_effect($r)).'</td><td>';foreach($r['errors'] as $err)echo '<div class="alert warn">'.e($err).'</div>';echo '<details><summary>View Products / Source</summary>';foreach($r['lines'] as $line)echo '<p>'.e($line['name'].' / '.$line['variation'].' × '.$line['qty']).'</p>';foreach($r['totals'] as $pid=>$qty){$p=gm_products()[$pid]??[];echo '<p>'.e(($p['master_sku']??'#'.$pid).' · '.($p['name']??'Product').' = '.$qty.' pcs').'</p>';}echo '</details>';
 if($review&&$r['errors']&&om_allowed()&&(access_profile()==='Admin'||(int)$b['created_by']===current_user()['id']))foreach($r['lines'] as $line){echo '<details class="om-correction"><summary>Correct Product / Bundle · row '.(int)$line['row'].'</summary>';om_form('om_correct',['upload_id'=>$id,'row_no'=>$line['row'],'revision'=>$b['revision'],'review_filter'=>$filter]);$line['product_id']=$line['components'][0]['product_id']??0;echo bundle_editor($line).'<label class="om-inline"><input type="checkbox" name="save_mapping" value="1"> Save exact SKU / variation mapping</label><button class="btn secondary">Save & Validate</button></form></details>';}echo '</td></tr>';}
 if(!$visible)echo '<tr><td colspan="4">No records in this category.</td></tr>';echo '</tbody></table></div>';echo rs8_pagination(count($visible),$offset,$size,['page'=>'outflow','platform'=>$pl,'upload_id'=>$id,'review_filter'=>$filter],'review_offset');if(!$reg&&$n['unregistered'])echo '<div class="om-note">Unregistered To Ship orders are excluded. Unregistered Shipped / Delivered / Completed orders remain flagged for checking after confirmation; no order or stock entry is automatically created.</div>';echo '<details class="os-rules"><summary>What happens to stocks?</summary><p>Registration reserves availability. The first confirmed dispatch deducts physical stock once. Delivered / Completed updates never repeat the deduction. Cancellation before dispatch releases its reservation; cancellation after posting requires return or reversal review.</p>';if($review)om_impact_panel($plan);echo '</details>';
 if($review&&om_allowed()&&(access_profile()==='Admin'||(int)$b['created_by']===current_user()['id'])){om_form('om_confirm',['upload_id'=>$id,'digest'=>$plan['digest']]);echo '<label class="om-inline"><input type="checkbox" name="review_ack" value="1" required> I reviewed the valid records, exclusions and stock effects.</label><div class="om-actions"><button class="btn primary"'.($reg&&$n['checking']?' disabled':'').'>'.($reg?'Confirm Registration':'Confirm Valid Updates').'</button></div></form>';if($reg&&$n['checking'])echo '<p class="os-help">Resolve every registration issue before confirming. No partial registration will be created.</p>';om_form('om_cancel',['upload_id'=>$id]);echo '<div class="om-actions"><button class="btn ghost">Cancel Upload / Back to File</button></div></form>';}else echo '<div class="om-actions"><a class="btn secondary" href="?page=outflow&platform='.e($pl).'&entry='.($reg?'register':'status').'">Upload Another File</a><a class="btn primary" href="?page=order_monitor&platform='.e($pl).'">View Monitoring</a></div>';
 echo '<details class="os-downloads"><summary>Source File & Downloads</summary><div class="om-original"><a class="btn ghost" href="order_monitor_action.php?download=original&id='.$id.'">Original Export</a><a class="btn secondary" href="order_monitor_action.php?download=validation&id='.$id.'">Validation Excel</a><a class="btn ghost" target="_blank" href="order_monitor_action.php?download=validation&id='.$id.'&format=print">Print / PDF</a><a class="btn ghost" href="?page=outflow&entry=history&platform='.e($pl).'">Upload History</a></div></details></div>';}
function os_exception_panel($pl){$all=os_open_exceptions($pl);if(!$all)return;echo '<div class="card"><h3>Unregistered Dispatches · Needs Checking</h3><p>Source exceptions only. No order or stock entries were created.</p>';$input=['download'=>'source_exceptions','platform'=>$pl];echo '<div class="om-actions"><a class="btn secondary" href="order_monitor_action.php?'.e(http_build_query($input+['format'=>'xlsx'])).'">Download Excel</a><a class="btn ghost" target="_blank" href="order_monitor_action.php?'.e(http_build_query($input+['format'=>'print'])).'">Print / PDF</a></div>';$offset=min(max(0,(int)($_GET['source_offset']??0)),max(0,(int)floor((count($all)-1)/10)*10));echo '<div class="om-table"><table class="table" data-server-paginated="1"><thead><tr><th>Order / Status</th><th>Snapshot / Responsible</th><th>Source / Follow-up</th></tr></thead><tbody>';foreach(array_slice($all,$offset,10) as $r){echo '<tr><td>'.e($r['order']).'<br>'.e($r['status']).'</td><td>'.e($r['snapshot']).'<br>'.e($r['owner_name']).'</td><td>';if(access_page_allowed('outflow'))echo '<a class="btn ghost sm" href="?page=outflow&upload_id='.(int)$r['upload_id'].'&review_filter=unregistered">View Source</a>';if(om_allowed()){echo '<details><summary>Record Resolution</summary>';om_form('os_resolve_exception',['exception_key'=>$r['key']]);echo '<label>Reason / verified reference<input name="reason" minlength="3" required></label><p class="small muted">This closes the follow-up only. Use the correct transaction workflow for any required stock movement.</p><button class="btn secondary">Save Resolution</button></form></details>';}echo '</td></tr>';}echo '</tbody></table></div>'.rs8_pagination(count($all),$offset,10,$_GET,'source_offset').'</div>';}
